def _csv(header: list[str], rows: list[list]) -> bytes:
    buf = io.StringIO()
    w = csv.writer(buf)
    w.writerow(header)
    w.writerows(rows)
    return buf.getvalue().encode()


def houses(n: int = 2000, seed: int = 7) -> bytes:
    rng = np.random.default_rng(seed)
    areas = {"Riverside": 1.35, "Old Town": 1.2, "Hillcrest": 1.1, "Parkview": 1.0, "Station": 0.92, "Industrial": 0.75}
    names = list(areas)
    rows = []
    for _ in range(n):
        area = names[rng.integers(len(names))]
        size = float(np.clip(rng.normal(110, 40), 30, 320))
        rooms = int(np.clip(round(size / 30 + rng.normal(0, 0.8)), 1, 8))
        age = int(np.clip(rng.exponential(25), 0, 120))
        dist = float(np.clip(rng.gamma(2.2, 2.5), 0.2, 30))
        garden = rng.random() < (0.25 + 0.5 * (dist > 4))
        cond = ["poor", "fair", "good", "excellent"][int(np.clip(rng.normal(2 - age / 60, 0.9), 0, 3))]
        price = (2600 * size ** 0.92 * areas[area] * (1 + 0.12 * ["poor", "fair", "good", "excellent"].index(cond))
                 * math.exp(-dist / 22) * (1.07 if garden else 1.0) * (1 - min(age, 80) / 400) + 9000 * rooms)
        price *= math.exp(rng.normal(0, 0.08))
        built = 2025 - age
        rows.append([round(size), rooms, built, area, round(dist, 1), "yes" if garden else "no", cond,
                     "" if rng.random() < 0.03 else int(round(price, -3))])
    return _csv(["size_m2", "bedrooms", "year_built", "area", "km_to_center", "garden", "condition", "price"], rows)


def spirals(n: int = 1200, seed: int = 3) -> bytes:
    rng = np.random.default_rng(seed)
    rows = []
    for i in range(n):
        arm = i % 2
        t = rng.uniform(0.25, 3.2) * math.pi
        r = t / (3.2 * math.pi)
        a = t + arm * math.pi
        rows.append([round(r * math.cos(a) + rng.normal(0, 0.025), 4), round(r * math.sin(a) + rng.normal(0, 0.025), 4), "A" if arm == 0 else "B"])
    return _csv(["x", "y", "arm"], rows)


_GOOD = ["great", "excellent", "lovely", "sturdy", "fast", "comfortable", "reliable", "beautiful", "perfect", "brilliant", "handy", "quiet"]
_BAD = ["terrible", "flimsy", "slow", "broken", "noisy", "disappointing", "cheap", "useless", "awful", "faulty", "uncomfortable", "ugly"]
_THINGS = ["kettle", "backpack", "lamp", "phone case", "chair", "blender", "headphones", "tent", "jacket", "keyboard", "water bottle", "umbrella"]
_PARTS = ["battery", "handle", "zip", "screen", "lid", "strap", "button", "cable", "fabric", "motor", "seal", "box"]


def reviews(n: int = 1600, seed: int = 11) -> bytes:
    rng = np.random.default_rng(seed)
    pick = lambda xs: xs[rng.integers(len(xs))]
    rows = []
    for _ in range(n):
        pos = rng.random() < 0.5
        mood, other = (_GOOD, _BAD) if pos else (_BAD, _GOOD)
        thing = pick(_THINGS)
        parts = [f"The {thing} is {pick(mood)}.",
                 f"The {pick(_PARTS)} feels {pick(mood)}." if rng.random() < 0.7 else f"The {pick(_PARTS)} is not {pick(other)}.",
                 pick(["Would buy again.", "Five stars.", "Recommended to friends."] if pos else ["Sent it back.", "One star.", "Avoid it."])
                 if rng.random() < 0.6 else "",
                 f"Only the {pick(_PARTS)} is a bit {pick(other)}." if rng.random() < 0.35 else ""]
        rng.shuffle(parts)
        text = " ".join(p for p in parts if p)
        if rng.random() < 0.05:          # a few mislabelled rows, like real data
            pos = not pos
        rows.append([text, "positive" if pos else "negative"])
    return _csv(["review", "sentiment"], rows)


def churn(n: int = 3000, seed: int = 5) -> bytes:
    from datetime import date, timedelta
    rng = np.random.default_rng(seed)
    plans = {"basic": 9.99, "plus": 19.99, "pro": 39.99}
    regions = ["north", "south", "east", "west"]
    rows = []
    for _ in range(n):
        plan = ["basic", "plus", "pro"][rng.choice(3, p=[0.5, 0.35, 0.15])]
        signup = date(2021, 1, 1) + timedelta(days=int(rng.integers(0, 1400)))
        months = (date(2024, 11, 1) - signup).days / 30.4
        calls = int(rng.poisson(1.2 + (plan == "basic")))
        login = int(min(120, rng.exponential(10)))
        sat = int(np.clip(round(rng.normal(3.8 - 0.35 * calls, 0.9)), 1, 5))
        score = -1.6 + 0.45 * calls + 0.045 * login - 0.55 * (sat - 3) - 0.025 * months + (0.5 if plan == "basic" else -0.3 if plan == "pro" else 0)
        left = rng.random() < 1 / (1 + math.exp(-score))
        rows.append([f"C{rng.integers(10**5, 10**6)}", signup.isoformat(), plan, plans[plan], calls, login, regions[rng.integers(4)], sat, "yes" if left else "no"])
    return _csv(["customer_id", "signed_up", "plan", "monthly_fee", "support_calls", "days_since_login", "region", "satisfaction", "left"], rows)


def shapes(per_class: int = 200, size: int = 48, seed: int = 9) -> bytes:
    """A zip with circles/, squares/ and triangles/ folders of small PNG drawings."""
    import zipfile
    from PIL import Image, ImageDraw
    rng = np.random.default_rng(seed)
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_STORED) as z:
        for kind in ("circles", "squares", "triangles"):
            for i in range(per_class):
                bg = tuple(int(v) for v in rng.integers(0, 256, 3))
                fg = tuple(int((v + 128) % 256) for v in bg)
                img = Image.new("RGB", (size, size), bg)
                d = ImageDraw.Draw(img)
                r = rng.uniform(size * 0.18, size * 0.38)
                cx, cy = rng.uniform(r + 2, size - r - 2, 2)
                a = rng.uniform(0, 2 * math.pi)
                if kind == "circles":
                    d.ellipse([cx - r, cy - r, cx + r, cy + r], fill=fg)
                else:
                    k = 4 if kind == "squares" else 3
                    pts = [(cx + r * math.cos(a + 2 * math.pi * j / k), cy + r * math.sin(a + 2 * math.pi * j / k)) for j in range(k)]
                    d.polygon(pts, fill=fg)
                arr = np.asarray(img, np.int16) + rng.normal(0, 12, (size, size, 3)).astype(np.int16)
                out = io.BytesIO()
                Image.fromarray(np.clip(arr, 0, 255).astype(np.uint8)).save(out, "PNG")
                z.writestr(f"shapes/{kind}/{kind[:-1]}_{i:03d}.png", out.getvalue())
    return buf.getvalue()


def sounds(per_class: int = 100, seconds: float = 0.6, rate: int = 8000, seed: int = 13) -> bytes:
    """A zip with whistles/, drums/, chords/ and chirps/ folders of short WAV clips (random pitch, loudness, noise)."""
    import wave
    import zipfile
    rng = np.random.default_rng(seed)
    n = int(seconds * rate)
    t = np.arange(n) / rate
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        for kind in ("whistles", "drums", "chords", "chirps"):
            for i in range(per_class):
                f0 = rng.uniform(220, 1100)
                start = rng.uniform(0, 0.15)
                on = np.clip((t - start) * 40, 0, 1)
                if kind == "whistles":       # one pure note with a little vibrato
                    x = np.sin(2 * np.pi * f0 * t + rng.uniform(2, 6) * np.sin(2 * np.pi * rng.uniform(4, 7) * t)) * on
                elif kind == "drums":        # noisy hits that die away quickly
                    x = np.zeros(n)
                    for hit in np.arange(start, seconds, rng.uniform(0.12, 0.3)):
                        k = int(hit * rate)
                        m = n - k
                        x[k:] += rng.normal(0, 1, m) * np.exp(-np.arange(m) / rate * rng.uniform(25, 60)) \
                            + np.sin(2 * np.pi * rng.uniform(60, 140) * np.arange(m) / rate) * np.exp(-np.arange(m) / rate * 18)
                elif kind == "chords":       # three notes together, each with overtones
                    x = sum(sum(np.sin(2 * np.pi * f0 * r * h * t) / h for h in (1, 2, 3)) for r in (1, 1.26, 1.5)) * on * np.exp(-t * rng.uniform(0.5, 2))
                else:                        # quick rising sweeps, repeated
                    x = np.zeros(n)
                    period = rng.uniform(0.08, 0.18)
                    phase = (t - start) % period
                    sweep = (phase < period * 0.6) * (t > start)
                    f = f0 * 2 + 3000 * phase / period
                    x = np.sin(2 * np.pi * np.cumsum(f) / rate) * sweep
                x = x / (np.abs(x).max() + 1e-9) * rng.uniform(0.2, 0.9) + rng.normal(0, rng.uniform(0.005, 0.05), n)
                pcm = (np.clip(x, -1, 1) * 32767).astype("<i2").tobytes()
                out = io.BytesIO()
                with wave.open(out, "wb") as w:
                    w.setnchannels(1)
                    w.setsampwidth(2)
                    w.setframerate(rate)
                    w.writeframes(pcm)
                z.writestr(f"sounds/{kind}/{kind[:-1]}_{i:03d}.wav", out.getvalue())
    return buf.getvalue()


def motions(per_class: int = 80, size: int = 40, frames: int = 10, seed: int = 17) -> bytes:
    """A zip with bouncing/, sliding/, spinning/ and growing/ folders of small animated GIFs."""
    import zipfile
    from PIL import Image, ImageDraw
    rng = np.random.default_rng(seed)
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_STORED) as z:
        for kind in ("bouncing", "sliding", "spinning", "growing"):
            for i in range(per_class):
                bg = tuple(int(v) for v in rng.integers(0, 120, 3))
                fg = tuple(int(v) for v in rng.integers(140, 256, 3))
                r = rng.uniform(size * 0.08, size * 0.16)
                cx, cy = rng.uniform(size * 0.3, size * 0.7, 2)
                speed = rng.uniform(0.6, 1.4)
                a0 = rng.uniform(0, 2 * np.pi)
                pics = []
                for f in range(frames):
                    img = Image.new("RGB", (size, size), bg)
                    d = ImageDraw.Draw(img)
                    s = np.sin(2 * np.pi * speed * f / frames + a0)
                    if kind == "bouncing":
                        y = cy + s * size * 0.3
                        d.ellipse([cx - r, y - r, cx + r, y + r], fill=fg)
                    elif kind == "sliding":
                        x = cx + s * size * 0.3
                        d.ellipse([x - r, cy - r, x + r, cy + r], fill=fg)
                    elif kind == "spinning":
                        a = a0 + 2 * np.pi * speed * f / frames
                        L = size * 0.3
                        d.line([cx - L * np.cos(a), cy - L * np.sin(a), cx + L * np.cos(a), cy + L * np.sin(a)], fill=fg, width=max(2, int(r * 0.7)))
                    else:
                        rr = r * (1.6 + 1.2 * s)
                        d.ellipse([cx - rr, cy - rr, cx + rr, cy + rr], fill=fg)
                    arr = np.asarray(img, np.int16) + rng.normal(0, 8, (size, size, 3)).astype(np.int16)
                    pics.append(Image.fromarray(np.clip(arr, 0, 255).astype(np.uint8)).quantize(32))
                out = io.BytesIO()
                pics[0].save(out, "GIF", save_all=True, append_images=pics[1:], duration=80, loop=0)
                z.writestr(f"motions/{kind}/{kind}_{i:03d}.gif", out.getvalue())
    return buf.getvalue()


def code() -> bytes:
    root = Path(__file__).resolve().parent.parent
    parts = []
    for p in sorted(root.rglob("*.py")):
        parts.append(f"# file: {p.relative_to(root.parent).as_posix()}\n" + p.read_text(encoding="utf-8", errors="replace"))
    return "\n\n".join(parts).encode()


def make(name: str) -> tuple[str, bytes]:
    """(filename, contents) for a sample."""
    if name == "houses":
        return "house_prices.csv", houses()
    if name == "spirals":
        return "two_spirals.csv", spirals()
    if name == "reviews":
        return "product_reviews.csv", reviews()
    if name == "churn":
        return "customer_churn.csv", churn()
    if name == "shapes":
        return "shapes.zip", shapes()
    if name == "sounds":
        return "sounds.zip", sounds()
    if name == "motions":
        return "motions.zip", motions()
    if name == "code":
        return "ai_room_code.txt", code()
    raise KeyError(name)
